// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {ICircuitNFT} from "./interfaces/ITapeOut.sol";

/// @title FeeVault
/// @notice Pull-based fee accounting shared by CurvePad and PositionLocker.
/// Fees split Container 50% / protocol 30% / sink 20%; rounding remainders go to the protocol.
/// Protocol and sink balances can be pushed by anyone. Creator (Container) balances can only be moved by the
/// Circuit's current holder, to either the Container or the holder's own wallet. The wallet route is a fallback
/// in case a TapeOut upgrade breaks Container withdrawals; holder-gating stops anyone forcing funds into a broken Container.
abstract contract FeeVault is ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 internal constant BPS = 10_000;
    uint256 internal constant CONTAINER_BPS = 5_000;
    uint256 internal constant SINK_BPS = 2_000;
    // protocol share = remainder (3_000 bps plus rounding)

    struct CircuitRef {
        address nft;
        uint256 id;
    }

    address public immutable protocol;
    address public immutable sink;

    mapping(address asset => mapping(address recipient => uint256)) public accrued;
    mapping(address asset => uint256) public totalAccrued;
    mapping(address container => CircuitRef) public circuitOf;

    event Claimed(address indexed asset, address indexed recipient, uint256 amount);
    event CreatorClaimed(address indexed container, address indexed asset, address indexed to, uint256 amount);

    error ZeroAddress();
    error CreatorClaimOnly();
    error UnknownContainer();
    error NotHolder();

    constructor(address protocol_, address sink_) {
        if (protocol_ == address(0) || sink_ == address(0)) revert ZeroAddress();
        protocol = protocol_;
        sink = sink_;
    }

    /// @notice Push accrued protocol or sink fees. Permissionless.
    function claim(address asset, address recipient) external nonReentrant {
        if (circuitOf[recipient].nft != address(0)) revert CreatorClaimOnly();
        _pay(asset, recipient, recipient);
    }

    /// @notice Move a Circuit's creator fees. Only the Circuit NFT's holder at claim time may call this.
    /// @param toHolder true sends to msg.sender (fallback), false sends to the Container.
    function claimCreator(address container, address asset, bool toHolder) external nonReentrant {
        CircuitRef memory ref = circuitOf[container];
        if (ref.nft == address(0)) revert UnknownContainer();
        if (ICircuitNFT(ref.nft).ownerOf(ref.id) != msg.sender) revert NotHolder();
        address to = toHolder ? msg.sender : container;
        uint256 amount = _pay(asset, container, to);
        emit CreatorClaimed(container, asset, to, amount);
    }

    function _registerContainer(address container, address nft, uint256 id) internal {
        if (circuitOf[container].nft == address(0)) circuitOf[container] = CircuitRef(nft, id);
    }

    function _accrueSplit(address asset, address container, uint256 amount) internal {
        if (amount == 0) return;
        uint256 toContainer = amount * CONTAINER_BPS / BPS;
        uint256 toSink = amount * SINK_BPS / BPS;
        accrued[asset][container] += toContainer;
        accrued[asset][sink] += toSink;
        accrued[asset][protocol] += amount - toContainer - toSink;
        totalAccrued[asset] += amount;
    }

    function _accrueProtocol(address asset, uint256 amount) internal {
        if (amount == 0) return;
        accrued[asset][protocol] += amount;
        totalAccrued[asset] += amount;
    }

    function _pay(address asset, address account, address to) private returns (uint256 amount) {
        amount = accrued[asset][account];
        if (amount == 0) return 0;
        accrued[asset][account] = 0;
        totalAccrued[asset] -= amount;
        IERC20(asset).safeTransfer(to, amount);
        emit Claimed(asset, to, amount);
    }
}

src/Graduator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {LaunchToken} from "./LaunchToken.sol";
import {CircHook} from "./CircHook.sol";
import {TickMath} from "./libraries/uniswap/TickMath.sol";
import {LiquidityAmounts} from "./libraries/uniswap/LiquidityAmounts.sol";
import {
    PoolKey,
    IPoolManager,
    IPositionManager,
    IAllowanceTransfer,
    V4Actions
} from "./interfaces/IUniswapV4.sol";

/// @title Graduator
/// @notice Moves a Complete curve into a locked full-range Uniswap v4 position in a CircHook pool. Deployed by CurvePad in
/// its constructor; no admin, callable only by CurvePad. Only Graduator can initialize a CircHook pool (enforced by the
/// hook), so the pool always opens at exactly the curve's final price: there is no pre-existing pool to normalise.
/// CurvePad hands over the LP tokens and the raise for one `graduate` call; the position goes to PositionLocker, token
/// dust is burned and leftover quote goes back to CurvePad, so this contract holds nothing between calls.
contract Graduator {
    using SafeERC20 for IERC20;
    using SafeCast for uint256;

    uint24 public constant POOL_FEE = 10_000; // 1%
    int24 public constant TICK_SPACING = 200;
    int24 public constant TICK_LOWER = -887_200; // full range, multiples of 200
    int24 public constant TICK_UPPER = 887_200;

    address public immutable pad;
    IPoolManager public immutable poolManager;
    IPositionManager public immutable positionManager;
    IAllowanceTransfer public immutable permit2;
    CircHook public immutable hook;
    address public immutable locker;

    struct Result {
        bytes32 poolId;
        uint256 positionId;
        uint256 tokenUsed;
        uint256 quoteUsed;
        uint256 quoteLeft;
    }

    error OnlyPad();
    error BadConfig();

    constructor(
        IPoolManager poolManager_,
        IPositionManager positionManager_,
        IAllowanceTransfer permit2_,
        CircHook hook_,
        address locker_
    ) {
        pad = msg.sender;
        poolManager = poolManager_;
        positionManager = positionManager_;
        permit2 = permit2_;
        hook = hook_;
        locker = locker_;
    }

    /// @notice The pool key every Circ launch graduates into.
    function poolKey(address token, address quote) public view returns (PoolKey memory key) {
        (address c0, address c1) = token < quote ? (token, quote) : (quote, token);
        key = PoolKey(c0, c1, POOL_FEE, TICK_SPACING, address(hook));
    }

    /// @notice CurvePad has transferred `tokenAmt` tokens and `quoteAmt` quote here.
    /// @param vQuote,vToken the curve's final reserves; the pool opens at vQuote / vToken.
    /// @param lockData forwarded to PositionLocker with the position NFT.
    function graduate(
        address token,
        address quote,
        uint256 vQuote,
        uint256 vToken,
        uint256 tokenAmt,
        uint256 quoteAmt,
        bytes calldata lockData
    ) external returns (Result memory r) {
        if (msg.sender != pad) revert OnlyPad();
        bool tokenIs0 = token < quote;
        PoolKey memory key = poolKey(token, quote);
        r.poolId = keccak256(abi.encode(key));
        uint160 sqrtPrice = _sqrtPriceX96(vQuote, vToken, tokenIs0);
        poolManager.initialize(key, sqrtPrice);

        (uint256 amt0, uint256 amt1) = tokenIs0 ? (tokenAmt, quoteAmt) : (quoteAmt, tokenAmt);
        uint128 liq = LiquidityAmounts.getLiquidityForAmounts(
            sqrtPrice, TickMath.getSqrtRatioAtTick(TICK_LOWER), TickMath.getSqrtRatioAtTick(TICK_UPPER), amt0, amt1
        );

        uint256 tokenBefore = IERC20(token).balanceOf(address(this));
        uint256 quoteBefore = IERC20(quote).balanceOf(address(this));
        r.positionId = positionManager.nextTokenId();
        _mint(key, liq, amt0, amt1, r.poolId);
        // Mint and settlement are done: from here on anyone may add or remove their own liquidity in this pool.
        hook.openPool(r.poolId);
        r.tokenUsed = tokenBefore - IERC20(token).balanceOf(address(this));
        r.quoteUsed = quoteBefore - IERC20(quote).balanceOf(address(this));

        positionManager.safeTransferFrom(address(this), locker, r.positionId, lockData);

        uint256 tokenDust = IERC20(token).balanceOf(address(this));
        if (tokenDust != 0) LaunchToken(token).burn(tokenDust);
        r.quoteLeft = IERC20(quote).balanceOf(address(this));
        if (r.quoteLeft != 0) IERC20(quote).safeTransfer(pad, r.quoteLeft);
    }

    /// @dev MINT_POSITION (owner = this) then SETTLE_PAIR, paid through Permit2. The hook admits exactly this one add; the
    /// pool stays closed to everyone else until `openPool` after this returns.
    function _mint(PoolKey memory key, uint128 liq, uint256 amt0, uint256 amt1, bytes32 poolId) internal {
        _approve(key.currency0, amt0);
        _approve(key.currency1, amt1);
        hook.allowAdd(poolId);

        bytes[] memory params = new bytes[](2);
        params[0] = abi.encode(
            key, TICK_LOWER, TICK_UPPER, uint256(liq), amt0.toUint128(), amt1.toUint128(), address(this), bytes("")
        );
        params[1] = abi.encode(key.currency0, key.currency1);
        positionManager.modifyLiquidities(
            abi.encode(abi.encodePacked(V4Actions.MINT_POSITION, V4Actions.SETTLE_PAIR), params), block.timestamp
        );

        _revoke(key.currency0);
        _revoke(key.currency1);
    }

    function _approve(address currency, uint256 amount) internal {
        IERC20(currency).forceApprove(address(permit2), amount);
        permit2.approve(currency, address(positionManager), amount.toUint160(), uint48(block.timestamp));
    }

    function _revoke(address currency) internal {
        IERC20(currency).forceApprove(address(permit2), 0);
        permit2.approve(currency, address(positionManager), 0, 0);
    }

    /// @dev sqrt(currency1/currency0) in Q64.96 at the curve's price (quote per token = vQuote / vToken).
    function _sqrtPriceX96(uint256 vQuote, uint256 vToken, bool tokenIs0) internal pure returns (uint160) {
        uint256 ratioX192 = tokenIs0 ? Math.mulDiv(vQuote, 1 << 192, vToken) : Math.mulDiv(vToken, 1 << 192, vQuote);
        uint256 s = Math.sqrt(ratioX192);
        if (s < TickMath.MIN_SQRT_RATIO || s >= TickMath.MAX_SQRT_RATIO) revert BadConfig();
        return uint160(s);
    }
}

